  test("'`${action}: shared identifier contract`, () => {
    for (const id of ['"'A1', ' A1 ', '\\t\\nA1\\r\\n', '\\u00a0A1\\u00a0']) {
      assert.deepEqual(run({action, id}), {
        id: 'A1',
        status: {find: 'open', cancel: 'cancelled', archive: 'archived'}[action],
      });
    }
    for (const id of [undefined, null, 1, true, {}, [], ['A1'], '', ' \\t\\n', '\\u00a0']) {
      assert.throws(() => run({action, id}), /"'^Error: invalid id$/);
    }
    for (const id of ['"' unknown ', ' a1 ', ' A 1 ']) {
      if (action === 'find') assert.equal(run({action, id}), null);
      else assert.throws(() => run({action, id}), /"'^Error: missing$/);
    }
  });
}
